import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.ResponseStatus;

/** A status change the claim's current status does not allow. */
@ResponseStatus(HttpStatus.CONFLICT)
public class ClaimStatusException extends RuntimeException {

    public ClaimStatusException(Long id, ClaimStatus from, ClaimStatus to) {
        super("Claim " + id + " cannot go from " + from + " to " + to);
    }
}
package net.officefloor.hq.app.claim;

/** Where a claim is in its life: DRAFT, then OPEN, then SETTLED; a DRAFT or OPEN claim may be VOID. */
public enum ClaimStatus {
    DRAFT, OPEN, SETTLED, VOID;

    /** Whether a claim in this status may move to the next one. */
    public boolean canMoveTo(ClaimStatus next) {
        return switch (next) {
            case OPEN -> this == DRAFT;
            case SETTLED -> this == OPEN;
            case VOID -> this == DRAFT || this == OPEN;
            case DRAFT -> false;
        };
    }

    /** Whether a claim in this status counts toward claimed and the totals. */
    public boolean counts() {
        return this == OPEN || this == SETTLED;
    }
}
-- A claim's due as it was when it was settled: its amount times its person's grade's rate then,
-- rounded half up to cents. Null while the claim is not settled, or when the grade had no rate
-- (that due stays live).
ALTER TABLE claim ADD COLUMN settled_due DECIMAL(14, 2);
-- A claim's number: given when it is opened, the next on its sheet (1, 2, ...), never reused.
-- A DRAFT has none and voiding a claim clears it. The sheet keeps the last number it gave out.
ALTER TABLE sheet ADD COLUMN last_claim_number BIGINT DEFAULT 0 NOT NULL;
ALTER TABLE claim ADD COLUMN claim_number BIGINT;

